if (durableCoreEvidence?.ok !== true || durableCoreEvidence?.status !== "HUMO17_RUNTIME_ZERO_COST_PREFLIGHT_READY" || durableCoreEvidence?.cheapCpuRecertificationRequired !== false || durableCoreEvidence?.resourceCreated !== false || durableCoreEvidence?.inferenceStarted !== false || Number(durableCoreEvidence?.activePods) !== 0 || Number(durableCoreEvidence?.paidStaleReceipts) !== 0 || durableCoreEvidence?.terminationVerified !== true || durableCoreEvidence?.networkVolumeRetained !== true || durableCoreEvidence?.networkVolumeId !== "1qm5wczocl" || durableCoreEvidence?.volumeId !== "1qm5wczocl" || durableCoreEvidence?.dataCenterId !== "EU-NL-1" || durableCoreEvidence?.coreManifestVerified !== true || durableCoreEvidence?.coreStagePodId !== stageReceipt?.podId || !/^[a-f0-9]{64}$/.test(durableReceiptSha256)) throw new Error("HUMO17_QUALITY_DURABLE_CORE_EVIDENCE_INVALID");
if (stageReceipt?.ok !== true || stageReceipt?.status !== "HUMO17_PERSISTENT_CORE_STAGED_AND_RELEASED" || stageReceipt?.physicalStageCertified !== true || stageReceipt?.coreManifestVerified !== true || stageReceipt?.terminationVerified !== true || stageReceipt?.networkVolumeRetained !== true || stageReceipt?.networkVolumeId !== "1qm5wczocl" || stageReceipt?.networkVolumeDataCenterId !== "EU-NL-1") throw new Error("HUMO17_QUALITY_HISTORICAL_CORE_ANCHOR_INVALID");
